const dialog = button.closest('dialog');
const inspector = panel.querySelector('[data-arms-inspector]');
const close = dialog.querySelector(':scope>button.btn');
const reset = panel.querySelector('[data-arms-reset]').parentElement;
inspector.style.removeProperty('max-height');
armsHeroMeasure(panel);
const bounds = function () {
  return {top:Math.max(dialog.getBoundingClientRect().top, close.getBoundingClientRect().bottom) + 8,
    bottom:Math.min(dialog.getBoundingClientRect().bottom, reset.getBoundingClientRect().top) - 8};
};
let safe = bounds();
const shortage = button.getBoundingClientRect().height - (safe.bottom - safe.top);
if (shortage > 0) {
  inspector.style.maxHeight = Math.max(44, inspector.getBoundingClientRect().height - shortage) + 'px';
  armsHeroMeasure(panel);
  safe = bounds();
}
for (let scroller = button.parentElement; scroller && dialog.contains(scroller); scroller = scroller.parentElement) {
  if (scroller.scrollHeight <= scroller.clientHeight || !/auto|scroll|overlay/.test(getComputedStyle(scroller).overflowY)) continue;
  const frame = scroller.getBoundingClientRect();
  const top = Math.max(safe.top, frame.top + scroller.clientTop);
  const bottom = Math.min(safe.bottom, frame.top + scroller.clientTop + scroller.clientHeight);
  const rect = button.getBoundingClientRect();
  const delta = rect.bottom > bottom ? rect.bottom - bottom : rect.top < top ? rect.top - top : 0;
  scroller.scrollTop += delta;
}
